pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        address bob = address(0x456);
        vm.deal(alice, 10 wei);
        vm.deal(bob, 10 wei);

        // Alice plays, wins (random==0 forced by block.timestamp and block.difficulty)
        vm.prank(alice);
        c.play{value: 10 wei}();

        // Bob plays, wins as well
        vm.prank(bob);
        c.play{value: 10 wei}();

